-- пропало: есть в старом, нет в новом
SELECT o.* FROM старый o
LEFT JOIN новый n ON n.id = o.id
WHERE n.id IS NULL;

-- появилось: есть в новом, нет в старом
SELECT n.* FROM новый n
WHERE NOT EXISTS (SELECT 1 FROM старый o WHERE o.id = n.id);

-- изменилось
SELECT … FROM новый n JOIN старый o ON o.id = n.id
WHERE n.поле IS NOT o.поле;
